using UnityEngine;using Alterverse.Characters;
namespace Alterverse.UI
{
public sealed class MainMenuController:MonoBehaviour
{
private enum Page{Home,Heroes,Settings}private static MainMenuController instance;private Page page;private bool visible=true,launching;private GUIStyle title,subtitle,button,primary,small,panel,heroName,sideLabel;private Texture2D dimTexture,zeroTexture,lumenTexture,whiteTexture;private int selectedHero;private float openedAt,launchAt;private readonly string[] heroes={"VEYR","KAELON","NYRA","ELYRA","MIRA","ROOK"};private readonly string[] roles={"ASSASSINE","TANK","MARKSMAN","MAGIER","SUPPORT","BRUISER"};
[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void AutoCreate(){if(FindAnyObjectByType<MainMenuController>()==null)new GameObject("DF_MainMenu").AddComponent<MainMenuController>();}
private void Awake(){if(instance!=null&&instance!=this){Destroy(gameObject);return;}instance=this;selectedHero=(int)PlayerHeroSelection.Selected;openedAt=Time.unscaledTime;Time.timeScale=0;dimTexture=MakeTexture(new Color(.008f,.006f,.02f,.97f));zeroTexture=MakeTexture(new Color(.19f,.025f,.30f,.55f));lumenTexture=MakeTexture(new Color(.015f,.42f,.48f,.42f));whiteTexture=MakeTexture(Color.white);}
private void Update(){if(launching&&Time.unscaledTime-launchAt>.62f)EnterMatch();}
private Texture2D MakeTexture(Color c){Texture2D t=new(1,1);t.SetPixel(0,0,c);t.Apply();return t;}private void OnDestroy(){if(instance==this)instance=null;DestroyTexture(dimTexture);DestroyTexture(zeroTexture);DestroyTexture(lumenTexture);DestroyTexture(whiteTexture);}private static void DestroyTexture(Texture2D t){if(t!=null)Destroy(t);}
private void OnGUI(){if(!visible)return;EnsureStyles();DrawBackground();if(launching){DrawLaunch();return;}switch(page){case Page.Heroes:DrawHeroes();break;case Page.Settings:DrawSettings();break;default:DrawHome();break;}}
private void DrawBackground(){GUI.DrawTexture(new Rect(0,0,Screen.width,Screen.height),dimTexture);float t=Time.unscaledTime-openedAt;float pulse=.5f+.5f*Mathf.Sin(t*1.35f);float collision=Mathf.Sin(t*.7f)*Screen.width*.006f;GUI.color=new Color(1,1,1,.74f+.16f*pulse);GUI.DrawTexture(new Rect(0,0,Screen.width*.505f+collision,Screen.height),zeroTexture);GUI.DrawTexture(new Rect(Screen.width*.495f+collision,0,Screen.width*.505f,Screen.height),lumenTexture);GUI.color=Color.white;float center=Screen.width*.5f+collision;for(int i=0;i<9;i++){float phase=t*(.65f+i*.045f)+i*1.71f;float y=(i+.5f)*Screen.height/9f+Mathf.Sin(phase*1.8f)*18;float x=center+Mathf.Sin(phase)*10;float w=2+((i%3)*1.2f);GUI.color=new Color(.75f,.45f,1f,.22f+.2f*pulse);GUI.DrawTexture(new Rect(x-w*.5f,y-22,w,44),whiteTexture);}GUI.color=Color.white;float seam=3+5*pulse;GUI.DrawTexture(new Rect(center-seam*.5f,0,seam,Screen.height),whiteTexture);GUI.Label(new Rect(24,Screen.height*.48f,Screen.width*.22f,32),"DIMENSION ZERO",sideLabel);GUI.Label(new Rect(Screen.width*.78f-24,Screen.height*.48f,Screen.width*.22f,32),"LUMEN",sideLabel);}
private void DrawHome(){float w=Mathf.Min(720,Screen.width*.9f),x=(Screen.width-w)*.5f,top=Screen.height*.12f;GUI.Label(new Rect(x,top,w,92),"DIMENSIONS FRONT",title);GUI.Label(new Rect(x,top+82,w,34),"FIGHT FOR YOUR REALITY",subtitle);GUI.Label(new Rect(x,top+119,w,26),$"{heroes[selectedHero]}  •  {roles[selectedHero]}",small);float bw=Mathf.Min(390,w*.72f),bx=(Screen.width-bw)*.5f,by=Mathf.Max(top+190,Screen.height*.48f);if(GUI.Button(new Rect(bx,by,bw,68),"SPIELEN",primary))BeginLaunch();if(GUI.Button(new Rect(bx,by+84,bw,50),"HELDEN",button))page=Page.Heroes;GUI.enabled=false;GUI.Button(new Rect(bx,by+146,bw,46),"RANGLISTE  •  BALD",button);GUI.enabled=true;if(GUI.Button(new Rect(bx,by+204,bw,44),"EINSTELLUNGEN",button))page=Page.Settings;GUI.Label(new Rect(x,Screen.height-42,w,22),"ZWEI REALITÄTEN. EINE FRONT.",small);}
private void DrawHeroes(){float w=Mathf.Min(760,Screen.width*.9f),x=(Screen.width-w)*.5f,y=Screen.height*.27f;GUI.Label(new Rect(x,Screen.height*.11f,w,62),"WÄHLE DEINE REALITÄT",title);GUI.Box(new Rect(x,y,w,218),GUIContent.none,panel);if(GUI.Button(new Rect(x+18,y+70,55,55),"‹",button))ChangeHero(-1);if(GUI.Button(new Rect(x+w-73,y+70,55,55),"›",button))ChangeHero(1);GUI.Label(new Rect(x+80,y+30,w-160,62),heroes[selectedHero],heroName);GUI.Label(new Rect(x+80,y+94,w-160,36),roles[selectedHero],subtitle);GUI.Label(new Rect(x+80,y+132,w-160,28),$"{selectedHero+1} / {heroes.Length}",small);GUI.Label(new Rect(x+80,y+164,w-160,28),"FÜR DAS NÄCHSTE MATCH AUSGEWÄHLT",small);if(GUI.Button(new Rect(x,y+240,180,48),"ZURÜCK",button))page=Page.Home;}
private void ChangeHero(int direction){selectedHero=(selectedHero+direction+heroes.Length)%heroes.Length;PlayerHeroSelection.Select((HeroId)selectedHero);}private void DrawSettings(){float w=Mathf.Min(620,Screen.width*.86f),x=(Screen.width-w)*.5f;GUI.Label(new Rect(x,Screen.height*.14f,w,62),"EINSTELLUNGEN",title);GUI.Box(new Rect(x,Screen.height*.30f,w,150),GUIContent.none,panel);GUI.Label(new Rect(x+25,Screen.height*.30f+30,w-50,34),"AUDIO, GRAFIK UND STEUERUNG",subtitle);GUI.Label(new Rect(x+25,Screen.height*.30f+78,w-50,28),"Wird nach dem Gameplay-Test aktiviert.",small);if(GUI.Button(new Rect(x,Screen.height*.30f+180,180,48),"ZURÜCK",button))page=Page.Home;}
private void BeginLaunch(){PlayerHeroSelection.Select((HeroId)selectedHero);launching=true;launchAt=Time.unscaledTime;}private void DrawLaunch(){float p=Mathf.Clamp01((Time.unscaledTime-launchAt)/.62f),ease=p*p*(3-2*p);float w=Mathf.Lerp(Screen.width*.02f,Screen.width*.72f,ease);GUI.color=new Color(1,1,1,.12f+.65f*ease);GUI.DrawTexture(new Rect(Screen.width*.5f-w*.5f,0,w,Screen.height),whiteTexture);GUI.color=Color.white;GUI.Label(new Rect(0,Screen.height*.43f,Screen.width,70),p>.48f?"ENTER THE FRONT":"REALITY COLLISION",heroName);}private void EnterMatch(){visible=false;Time.timeScale=1;gameObject.SetActive(false);}
private void EnsureStyles(){if(title!=null)return;title=new GUIStyle(GUI.skin.label){fontSize=Mathf.Clamp(Screen.width/18,34,66),fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};subtitle=new GUIStyle(GUI.skin.label){fontSize=Mathf.Clamp(Screen.width/48,15,23),fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};button=new GUIStyle(GUI.skin.button){fontSize=Mathf.Clamp(Screen.width/48,15,22),fontStyle=FontStyle.Bold};primary=new GUIStyle(button){fontSize=Mathf.Clamp(Screen.width/38,20,29)};small=new GUIStyle(GUI.skin.label){fontSize=13,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};panel=new GUIStyle(GUI.skin.box);heroName=new GUIStyle(title){fontSize=Mathf.Clamp(Screen.width/24,27,46)};sideLabel=new GUIStyle(small){fontSize=12,alignment=TextAnchor.MiddleCenter};}
}
}
